    background: color-mix(in srgb, var(--pi-cor) 15%, transparent);
  }
  .pi :global(svg) { width: 58%; height: 58%; }
  .pi-txt { font-size: 11px; font-weight: 600; letter-spacing: 0.02em; }
</style>
